val deck = (1..52).map { Card((it - 1) % 13 + 1, (it - 1) / 13) }.toMutableList()
deck.shuffle(rng)
for (i in tableau.indices) {
    for (j in 0 until i + 1) {
        val card = deck.removeAt(0)
        tableau[i].add(card)
        if (j == i) card.faceUp = true
    }
}
stock.addAll(deck)'

